template:
% 参数由系统自动注入：\def\k{2} \def\showpoint{1} \def\px{1.5} \def\showrect{0} \def\showtri{0} \def\showsym{0} \def\labelp{P}
% 点 P 纵坐标 k/x，对称视图半宽纳入点 P
\pgfmathsetmacro{\kabs}{abs(\k)}
\pgfmathsetmacro{\py}{\k/\px}
\pgfmathsetmacro{\pyabs}{abs(\py)}
\pgfmathsetmacro{\v}{max(3.2, abs(\px)+0.9, \pyabs+0.9)}
\pgfmathtruncatemacro{\vr}{ceil(\v)}
\pgfmathsetmacro{\xleft}{-\vr}
\pgfmathsetmacro{\xright}{\vr}
\pgfmathsetmacro{\ybottom}{-\vr}
\pgfmathsetmacro{\ytop}{\vr}
% 曲线近端：贴 y 轴处截断，远端到视图边缘
\pgfmathsetmacro{\xnear}{\kabs/(\ytop+0.3)}
\pgfmathsetmacro{\xrange}{\xright-\xleft}
\pgfmathsetmacro{\yrange}{\ytop-\ybottom}
\pgfmathsetmacro{\figscale}{6.5/max(\xrange,\yrange)}
\pgfmathsetmacro{\dotr}{1.6/\figscale}
\pgfmathsetmacro{\khalf}{\kabs/2}
\begin{tikzpicture}[scale=\figscale, every node/.style={font=\small, fill=none, inner sep=1.5pt}]
  % ===== 坐标系（坐标轴即渐近线）=====
  \draw[->, thick] (\xleft-0.5,0) -- (\xright+0.6,0) node[right] {$x$};
  \draw[->, thick] (0,\ybottom-0.5) -- (0,\ytop+0.6) node[above] {$y$};
  \node[below left, font=\tiny] at (0,0) {$O$};
  \foreach \x in {\xleft,...,\xright} {
    \ifnum\x=0\else
      \draw (\x,0.12/\figscale) -- (\x,-0.12/\figscale);
      \node[below, font=\tiny, inner sep=1pt] at (\x,0) {$\x$};
    \fi
  }
  \foreach \y in {\ybottom,...,\ytop} {
    \ifnum\y=0\else
      \draw (0.12/\figscale,\y) -- (-0.12/\figscale,\y);
      \node[left, font=\tiny, inner sep=1pt] at (0,\y) {$\y$};
    \fi
  }
  % ===== 对称轴 =====
  \ifnum\showsym>0
    \draw[dashed, gray] (-\vr,-\vr) -- (\vr,\vr) node[above right, font=\tiny, gray] {$y=x$};
    \draw[dashed, gray] (-\vr,\vr) -- (\vr,-\vr) node[below right, font=\tiny, gray] {$y=-x$};
  \fi
  % ===== 矩形 / 三角形面积（k 的几何意义）=====
  \ifnum\showrect>0
    \fill[blue!10, draw=none] (0,0) rectangle (\px,\py);
    \node[font=\tiny, blue!60!black] at (\px/2,\py/2) {$S=\kabs$};
  \fi
  \ifnum\showtri>0
    \fill[blue!18, draw=none] (0,0) -- (\px,0) -- (\px,\py) -- cycle;
    \node[font=\tiny, blue!60!black] at (2*\px/3,\py/3) {$S=\khalf$};
  \fi
  % ===== 双曲线两支 =====
  \draw[thick, domain=\xnear:\xright, samples=80, smooth] plot (\x, {\k/\x});
  \draw[thick, domain=-\xright:-\xnear, samples=80, smooth] plot (\x, {\k/\x});
  % ===== 点 P 与垂线段、垂足 =====
  \ifnum\showpoint>0
    \draw[dashed, gray] (\px,\py) -- (\px,0);
    \draw[dashed, gray] (\px,\py) -- (0,\py);
    \fill (\px,0) circle [radius=\dotr pt];
    \fill (0,\py) circle [radius=\dotr pt];
    \node[below=1pt, font=\tiny, inner sep=1pt] at (\px,0) {$M$};
    \node[left, font=\tiny] at (0,\py) {$N$};
    \fill (\px,\py) circle [radius=\dotr pt];
    \ifdim\px pt>0pt
      \node[above right, font=\tiny] at (\px,\py) {$\labelp$};
    \else
      \node[below left, font=\tiny] at (\px,\py) {$\labelp$};
    \fi
  \fi
\end{tikzpicture}
